function compute(s) {
  var a = s.a, b = s.b, bb = b[0] * b[0] + b[1] * b[1];
  var dot = a[0] * b[0] + a[1] * b[1];
  var out = { values: { dot: dot }, series: { a: a, b: b }, matrices: {} };
  if (bb === 0) { out.warning = 'b is the zero vector, so there is no direction to project onto.'; return out; }
  var c = dot / bb, p = [c * b[0], c * b[1]], r = [a[0] - p[0], a[1] - p[1]];
  out.values.coef = c; out.values.resid_dot_b = r[0] * b[0] + r[1] * b[1];
  out.series.p = p; out.series.r = r;
  out.matrices.drop = [a, p];
  out.matrices.cloud = s.showData ? [[-3, -1.2], [-1.5, -0.1], [0.5, 0.4], [2, 0.3], [3.5, 1.1], [1, -0.4]] : [];
  return out;
}
